		if len(prefix) == limit || result.Score.DistinctTerms < minTerms {
			break
		}
		kind := class(result)
		if _, ok := classes[kind]; ok {
			continue
		}
		classes[kind] = struct{}{}
		selectResult(i)
	}
	for i, result := range results {
		if len(prefix) == limit || result.Score.DistinctTerms < minTerms {
			break
		}
		if selected[i] {
			continue
		}
		if _, ok := paths[result.Path]; ok {
